-- FlowCanvas initial schema
-- Design notes:
--  * Identifiers are UUIDs generated by the client for nodes/edges so that a graph can be
--    round-tripped between the browser canvas and the database without server-side remapping.
--  * Node configuration is JSONB: it is schemaless, per node type, and evolves with the
--    node taxonomy without a migration.
--  * Execution history is a first-class table so a run can be inspected after the fact.

CREATE TABLE workflows (
    id          UUID         PRIMARY KEY,
    name        VARCHAR(120) NOT NULL,
    description TEXT,
    status      VARCHAR(20)  NOT NULL DEFAULT 'DRAFT',
    created_at  TIMESTAMPTZ  NOT NULL,
    updated_at  TIMESTAMPTZ  NOT NULL,
    CONSTRAINT workflows_status_chk CHECK (status IN ('DRAFT', 'PUBLISHED', 'ARCHIVED'))
);

CREATE INDEX idx_workflows_updated_at ON workflows (updated_at DESC);

CREATE TABLE workflow_nodes (
    id          UUID         PRIMARY KEY,
    workflow_id UUID         NOT NULL REFERENCES workflows (id) ON DELETE CASCADE,
    node_key    VARCHAR(64)  NOT NULL,
    type        VARCHAR(32)  NOT NULL,
    label       VARCHAR(120) NOT NULL,
    position_x  DOUBLE PRECISION NOT NULL,
    position_y  DOUBLE PRECISION NOT NULL,
    config      JSONB        NOT NULL DEFAULT '{}'::jsonb,
    CONSTRAINT workflow_nodes_type_chk
        CHECK (type IN ('TEXT_INPUT', 'PROMPT_TEMPLATE', 'AI_MODEL', 'OUTPUT')),
    CONSTRAINT workflow_nodes_key_uq UNIQUE (workflow_id, node_key)
);

CREATE INDEX idx_workflow_nodes_workflow ON workflow_nodes (workflow_id);

CREATE TABLE workflow_edges (
    id            UUID        PRIMARY KEY,
    workflow_id   UUID        NOT NULL REFERENCES workflows (id) ON DELETE CASCADE,
    source_id     UUID        NOT NULL REFERENCES workflow_nodes (id) ON DELETE CASCADE,
    target_id     UUID        NOT NULL REFERENCES workflow_nodes (id) ON DELETE CASCADE,
    source_handle VARCHAR(64),
    target_handle VARCHAR(64),
    CONSTRAINT workflow_edges_no_self_loop CHECK (source_id <> target_id),
    CONSTRAINT workflow_edges_uq UNIQUE (workflow_id, source_id, target_id)
);

CREATE INDEX idx_workflow_edges_workflow ON workflow_edges (workflow_id);
CREATE INDEX idx_workflow_edges_source ON workflow_edges (source_id);
CREATE INDEX idx_workflow_edges_target ON workflow_edges (target_id);

CREATE TABLE workflow_executions (
    id          UUID        PRIMARY KEY,
    workflow_id UUID        NOT NULL REFERENCES workflows (id) ON DELETE CASCADE,
    status      VARCHAR(20) NOT NULL,
    started_at  TIMESTAMPTZ NOT NULL,
    finished_at TIMESTAMPTZ,
    duration_ms BIGINT,
    error       TEXT,
    CONSTRAINT workflow_executions_status_chk
        CHECK (status IN ('PENDING', 'RUNNING', 'SUCCESS', 'FAILED', 'CANCELLED'))
);

CREATE INDEX idx_workflow_executions_workflow ON workflow_executions (workflow_id, started_at DESC);

CREATE TABLE node_executions (
    id           UUID        PRIMARY KEY,
    execution_id UUID        NOT NULL REFERENCES workflow_executions (id) ON DELETE CASCADE,
    node_id      UUID        NOT NULL,
    node_key     VARCHAR(64) NOT NULL,
    node_type    VARCHAR(32) NOT NULL,
    label        VARCHAR(120) NOT NULL,
    status       VARCHAR(20) NOT NULL,
    sequence     INTEGER     NOT NULL,
    output       TEXT,
    error        TEXT,
    started_at   TIMESTAMPTZ NOT NULL,
    finished_at  TIMESTAMPTZ,
    duration_ms  BIGINT,
    CONSTRAINT node_executions_status_chk
        CHECK (status IN ('PENDING', 'RUNNING', 'SUCCESS', 'FAILED', 'SKIPPED'))
);

CREATE INDEX idx_node_executions_execution ON node_executions (execution_id, sequence);
